insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p96', 'allemand', '3AS', 14, 96, 'L5 3AS p96 — Die Medien dürfen ohne Behinderung arbeiten (dürfen + mögen)', E'Die Medien dürfen ohne Behinderung arbeiten.\n1. Üben Sie zu zweit wie im Beispiel.\ndürfen : Erlaubnis / Verbot · höfliche Frage\n- Darf ich heute Abend ins Kino gehen ? — Ja, du darfst ins Kino gehen.\nWörter : ins Kino gehen · ins Theater gehen · Fußball spielen · am Computer arbeiten · Freunde besuchen\n2. Ersetzen Sie die unterstrichenen Wörter durch dürfen.\n- Meine Eltern verbieten mir, allein am Abend auszugehen. Sie sagen mir, du …\n- Der Lehrer erlaubt uns, die Taschenrechner zu nutzen. Er sagt uns, ihr …\n- Der Schulleiter verbietet den Schülern, in der Schule zu rauchen. Er sagt ihnen, sie …\n- Erlauben Sie mir, Ihr Handy zu benutzen. … ich … ?\n3. Üben Sie zu zweit wie im Beispiel.\nmögen : gern haben / Lust haben\n- Welches Medium hast du gern ? — Ich mag die Zeitung am liebsten.\nWörter : die Zeitung · das Internet · der Hörfunk · das Fernsehen · die Zeitschriften\n4. Ersetzen Sie die unterstrichenen Wörter durch mögen.\n- Ich habe das Kino gern. → Ich …\n- Die Kinder haben die Computerspiele gern. → Sie …\n- Ich habe das chinesische Essen gern. → Ich …\n- Mein Großvater hat das Radio gern. → Er …\n- Ich habe Lust einen Roman zu lesen. → Ich …', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p97', 'allemand', '3AS', 14, 97, 'L5 3AS p97 — Ein Journalist fragt Jugendliche : Paul/Steffi/Hans/Anna (sowohl…als auch · entweder…oder · weder…noch · zwar…aber)', E'Ein Journalist fragt einige Jugendlichen, wie sie sich über wichtige Ereignisse informieren.\nPaul 18 : Ich informiere mich sowohl durch das Fernsehen als auch durch das Radio. Wenn ich mittags zu Hause bin, höre ich Radio, und abends schaue ich mir meistens die Nachrichten im Fernsehen an.\nSteffi 18 : Es kommt darauf an, wie ich Zeit habe. Ich sehe dann entweder die Nachrichten im Fernsehen oder lese die Zeitung. Durch das Fernsehen wird man schneller über alles informiert. Das Zeitungslesen braucht viel Zeit. Die Artikel sind auch manchmal schwierig zu verstehen.\nHans 17 : Ich informiere mich weder durch das Fernsehen noch durch die Zeitung. Ich höre sehr viel Radio. Dort sind die Nachrichten immer ganz aktuell. Außerdem kann man beim Radiohören nebenher noch etwas anderes machen, zum Beispiel Hausaufgaben.\nAnna 19 : Ich sehe zwar ab und zu die Nachrichten im Fernsehen, aber meistens schaue ich im Internet nach, das ist praktischer. Da brauche ich nicht auf die Zeit zu achten, ich kann mich informieren, wann ich will.\n1. Wer informiert sich wie ? Kreuzen Sie an.\nTabelle : durch Zeitung und Fernsehen · durch Zeitung oder Fernsehen · nicht durch Fernsehen und nicht durch Zeitung · durch Internet, manchmal Fernsehen · durch Radio und Fernsehen — Paul · Steffi · Hans · Anna', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p98', 'allemand', '3AS', 14, 98, 'L5 3AS p98 — Wer sagt was ? (indirekte Rede) + Ergänzen + Antworten', E'2. Wer sagt was ?\n- Durch das Fernsehen wird man schneller informiert.\n- Das Internet ist praktischer.\n- Im Radio sind die Nachrichten immer aktuell.\n- Ich informiere mich durch das Fernsehen und das Radio.\nBeginnen Sie mit : Anna sagt, … · Paul sagt, … · Steffi sagt, … · Hans sagt, …\n3. Ergänzen Sie. (nebenher · Artikel · ab und zu · Nachrichten · achten)\n- Viele Eltern … darauf, dass ihre Kinder nicht so oft fernsehen.\n- Abends sehe ich mir die Welt … an.\n- Die Zeitungs … sind oft zu schwer zu lesen.\n- Die Jugendlichen hören meistens Musik … lesen sie ihre E-Mails.\n- Meine Schwester kauft … ein Jugendmagazin.\n4. Antworten Sie.\n1. Wofür interessiert sich Paul ?\n2. Warum hat Steffi das Fernsehen lieber als die Zeitung ?\n3. Welches Informationsmittel hat Hans am liebsten ? Warum ?\n4. Weshalb hat Anna das Internet gern ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p99', 'allemand', '3AS', 14, 99, 'L5 3AS p99 — entweder…oder + weder…noch (Übungen)', E'Ich sehe entweder fern oder surfe im Internet.\n1. Üben Sie zu zweit wie im Beispiel.\n- Was machen Sie am Abend ? — Ich sehe entweder fern oder surfe im Internet.\n(… entweder … oder …)\nWörter : fernsehen/im Internet surfen · SMS schreiben/mit Freunden telefonieren · Naturfilm/Science Fiction sich ansehen · am Computer spielen/Sport treiben · in die Disco/ins Kino gehen\n2. Bilden Sie Sätze mit entweder … oder.\n- Sportsendungen / Dokumentarfilme\n- Kulturelle Sendungen / politische Sendungen\n- Dokumentarfilme / Spielfilme\n- Die Abendnachrichten / der Wetterbericht\n- Unterhaltungssendungen / Trickfilme\nIch lese weder die Zeitung noch die Zeitschrift…\n1. Üben Sie zu zweit wie im Beispiel.\n- Sehen Sie fern oder hören Sie Radio ? — Ich sehe weder fern noch höre ich das Radio.\n(… weder … noch …)\nWörter : fernsehen/Radio hören · Zeitungen/Jugendmagazin lesen · Filme/Videoclips sich ansehen · Computer benutzen/mit dem Gameboy spielen · mit dem Handy anrufen/über Skype chatten\n2. Was mögen Sie gern ? Antworten Sie mit weder … noch.\n- Das Fernsehen / das Internet\n- Computerspiele / Romane\n- Kino / Theater\n- Chatten / surfen\n- E-Mails / Briefe\n- Die Unterhaltungssendung / Verkaufssendung', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p100', 'allemand', '3AS', 14, 100, 'L5 3AS p100 — Was passt zusammen ? (zweiteilige Konnektoren)', E'3. Was passt zusammen ?\n1. Entweder kauft er eine Tageszeitung — g) oder eine Zeitschrift.\n2. Er nutzt sowohl das Telefon — f) als auch das Handy.\n3. Wir gehen weder ins Theater — e) noch ins Kino.\n4. Diese Familie hat sowohl einen Fernseher — b) als auch ein Videogerät.\n5. Meine Eltern schenken mir weder ein Handy — c) noch einen Computer.\n6. Ich kann heute entweder eine E-Mail schreiben — d) oder einen Text übersetzen.\n7. Der Verkäufer spricht sowohl Englisch — a) als auch Spanisch fließend.\nLösungstabelle : 1 → g', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
